function trIndentWidth(line){
  var w=0;
  for(var i=0;i<line.length;i++){
    if(line[i]===' ') w++;
    else if(line[i]==='\t') w+=4;
    else break;
  }
  return w;
}
function trStripGlyph(line){
  return line.replace(/^[\s\u2502\u251c\u2514\u2500|`+\-]*[\s]?/, function(mm){
    return mm.replace(/[^\s]/g,' ');
  });
}
function trParseIndent(text){
  var raw=String(text||'').replace(/\r\n?/g,'\n').split('\n');
  var lines=[];
  for(var i=0;i<raw.length;i++){
    if(!raw[i].trim()) continue;
    var norm = /[\u2502\u251c\u2514\u2500]/.test(raw[i]) ? trStripGlyph(raw[i]) : raw[i];
    lines.push({ indent:trIndentWidth(norm), name:norm.trim().replace(/\/$/,''), dir:/\/$/.test(norm.trim()) });
  }
  if(!lines.length) return { error:'请输入树形文本' };
  var root={ name:'', children:[], indent:-1 }, stack=[root];
  for(var j=0;j<lines.length;j++){
    var l=lines[j];
    while(stack.length>1 && stack[stack.length-1].indent >= l.indent) stack.pop();
    var node={ name:l.name, children:[], indent:l.indent, dir:l.dir };
    stack[stack.length-1].children.push(node);
    stack.push(node);
  }
  return { error:null, root:root, count:lines.length };
}
function trRender(root, ascii){
  var G = ascii ? { tee:'|-- ', last:'`-- ', bar:'|   ', gap:'    ' }
                : { tee:'\u251c\u2500\u2500 ', last:'\u2514\u2500\u2500 ', bar:'\u2502   ', gap:'    ' };
  var out=[];
  function walk(node, prefix){
    for(var i=0;i<node.children.length;i++){
      var c=node.children[i], last = i===node.children.length-1;
      out.push(prefix + (last?G.last:G.tee) + c.name + (c.children.length?'/':''));
      walk(c, prefix + (last?G.gap:G.bar));
    }
  }
  walk(root, '');
  return out.join('\n');
}
function trToJson(root){
  function conv(node){
    if(!node.children.length) return null;
    var o={};
    for(var i=0;i<node.children.length;i++) o[node.children[i].name]=conv(node.children[i]);
    return o;
  }
  return conv(root) || {};
}
function trFromJson(obj){
  function build(o, name){
    var node={ name:name, children:[] };
    if(o && typeof o==='object' && !Array.isArray(o)){
      var keys=Object.keys(o);
      for(var i=0;i<keys.length;i++) node.children.push(build(o[keys[i]], keys[i]));
    } else if(Array.isArray(o)){
      for(var j=0;j<o.length;j++){
        if(o[j] && typeof o[j]==='object') node.children.push(build(o[j], '['+j+']'));
        else node.children.push({ name:String(o[j]), children:[] });
      }
    }
    return node;
  }
  return build(obj, '');
}
function trStats(root){
  var files=0, dirs=0, maxDepth=0;
  function walk(node, d){
    for(var i=0;i<node.children.length;i++){
      var c=node.children[i];
      if(c.children.length){ dirs++; } else { files++; }
      if(d>maxDepth) maxDepth=d;
      walk(c, d+1);
    }
  }
  walk(root, 1);
  return { files:files, dirs:dirs, total:files+dirs, maxDepth:maxDepth };
}
function trPaths(root){
  var out=[];
  function walk(node, prefix){
    for(var i=0;i<node.children.length;i++){
      var c=node.children[i], p=prefix + c.name + (c.children.length?'/':'');
      out.push(p);
      walk(c, prefix + c.name + '/');
    }
  }
  walk(root, '');
  return out;
}
function trFromPaths(text){
  var lines=String(text||'').split(/\n+/).filter(function(l){ return l.trim(); });
  if(!lines.length) return { error:'请输入路径列表' };
  var root={ name:'', children:[], index:{} };
  for(var i=0;i<lines.length;i++){
    var segs=lines[i].trim().replace(/^\.?\//,'').split('/').filter(function(s){ return s!==''; });
    var node=root;
    for(var j=0;j<segs.length;j++){
      var hit=null;
      for(var k=0;k<node.children.length;k++) if(node.children[k].name===segs[j]){ hit=node.children[k]; break; }
      if(!hit){ hit={ name:segs[j], children:[] }; node.children.push(hit); }
      node=hit;
    }
  }
  return { error:null, root:root, count:lines.length };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { trIndentWidth:trIndentWidth, trParseIndent:trParseIndent, trRender:trRender,
    trToJson:trToJson, trFromJson:trFromJson, trStats:trStats, trPaths:trPaths, trFromPaths:trFromPaths };
}
if (typeof window !== 'undefined') {
  window.TreeForgePure = { trIndentWidth:trIndentWidth, trParseIndent:trParseIndent, trRender:trRender,
    trToJson:trToJson, trFromJson:trFromJson, trStats:trStats, trPaths:trPaths, trFromPaths:trFromPaths };
}
